964	func mergeCheckpointListEntries(preferred, additional []checkpointListEntry, limit int) []checkpointListEntry {
965		merged := make([]checkpointListEntry, 0, len(preferred)+len(additional))
966		seen := make(map[string]struct{}, len(preferred)+len(additional))
967		for _, entries := range [][]checkpointListEntry{preferred, additional} {
968			for _, entry := range entries {
969				if entry.CheckpointID == "" {
970					continue
971				}
972				if _, ok := seen[entry.CheckpointID]; ok {
973					continue
974				}
975				seen[entry.CheckpointID] = struct{}{}
976				merged = append(merged, entry)
977			}
978		}
979		if limit > 0 && len(merged) > limit {
980			merged = merged[:limit]
981		}
982		return merged
