1016	func listRoutedCheckpoints(ctx context.Context, runner CommandRunner, repoDir, entireBinary string, limit int, searchAll bool) ([]checkpointListEntry, []string, error) {
1017		args := []string{"checkpoint", "explain", "--json"}
1018		if searchAll {
