1020		}
1021		// The external CLI rejects an explicitly passed non-positive --limit, and
1022		// the unlimited default here is 0: omit the flag entirely to mean "all".
1023		if limit > 0 {
1024			args = append(args, "--limit", strconv.Itoa(limit))
1025		}
1026		stdout, stderr, err := runner.Run(ctx, repoDir, entireBinary, args...)
1027		warnings := routedCheckpointWarnings(stderr)
1028		if err != nil {
1029			return nil, warnings, fmt.Errorf("list checkpoints: %w", err)
1030		}
1031	
1032		var checkpoints []checkpointListEntry
1033		if err := decodeHostCLIJSON(stdout, &checkpoints); err != nil {
