1069	// routedCheckpointWarnings preserves ordinary stderr diagnostics while
1070	// recognizing Entire's additive complete-scope status line. The checkpoint
1071	// array on stdout intentionally remains backward-compatible; this stable
1072	// stderr record is what prevents an empty or partial array from being mistaken
1073	// for a complete inventory. Its payload contains codes and counts only.
1074	func routedCheckpointWarnings(data []byte) []string {
1075		text := strings.TrimSpace(string(data))
1076		if text == "" {
1077			return nil
1078		}
1079		lines := strings.Split(text, "\n")
1080		warnings := make([]string, 0, len(lines))
1081		for _, line := range lines {
1082			line = strings.TrimSpace(line)
1083			if line == "" {
1084				continue
1085			}
1086			if payload, ok := strings.CutPrefix(line, entireCheckpointScopePrefix); ok {
1087				warnings = append(warnings, checkpointScopeWarning(payload))
1088				continue
1089			}
1090			// Older Entire versions exposed remote discovery degradation as a human
1091			// warning only. Classify that legacy line conservatively too, so upgrading
1092			// Brain before Entire cannot reintroduce a false-complete manifest.
1093			if strings.Contains(line, "could not reach checkpoint remote; showing local checkpoints only") {
1094				warnings = append(warnings, checkpointScopeIncompleteCode+": Entire could not enumerate the configured checkpoint remote")
1095				continue
1096			}
1097			warnings = append(warnings, "checkpoint list: "+line)
1098		}
1099		return warnings
1100	}
