1102	func checkpointScopeWarning(payload string) string {
1103		var status routedCheckpointScopeStatus
1104		if err := json.Unmarshal([]byte(payload), &status); err != nil || status.SchemaVersion != 1 || status.Code != checkpointScopeIncompleteCode || status.Complete {
1105			return checkpointScopeIncompleteCode + ": Entire emitted an invalid or contradictory checkpoint scope status"
1106		}
1107		parts := make([]string, 0, len(status.Issues))
1108		for _, issue := range status.Issues {
1109			code := strings.TrimSpace(issue.Code)
1110			if code == "" {
1111				continue
1112			}
1113			count := issue.Count
1114			if count <= 0 {
1115				count = 1
1116			}
1117			parts = append(parts, fmt.Sprintf("%s=%d", code, count))
1118		}
1119		sort.Strings(parts)
1120		if len(parts) == 0 {
1121			return checkpointScopeIncompleteCode + ": Entire reported incomplete checkpoint enumeration"
1122		}
1123		return checkpointScopeIncompleteCode + ": Entire reported incomplete checkpoint enumeration (" + strings.Join(parts, ", ") + ")"
1124	}
