// told which vendor's agent will be reading their repository from now on.
func TestSetupDetectAgentAnnouncesExceptUnderJSON(t *testing.T) {
	clearAgentHarnessEnv(t)
	for _, jsonMode := range []bool{false, true} {
		repoDir := t.TempDir()
		runner := agentAvailability("codex")
		var stderr bytes.Buffer
		cmd := &cobra.Command{}
		cmd.SetOut(&bytes.Buffer{})
		cmd.SetErr(&stderr)
		steps := resolveSetupSteps(cmd, Options{Runner: runner, Now: time.Now}, setupCommandOptions{json: jsonMode, model: "opus"}, repoDir, "entire-brain", setupSteps{})
		if agent := steps.detectAgent(context.Background()); agent != "codex" {
			t.Fatalf("json=%v: setup detected agent = %q, want codex", jsonMode, agent)
		}
		announced := strings.Contains(stderr.String(), "auto-selected codex")
		if jsonMode {
			// The model is checked FIRST so this guard can be shown failing on
			// its own: the agent guard below would otherwise always fire first
			// and the model half would never be observed red.
			if strings.Contains(stderr.String(), "opus") {
				t.Fatalf("json: setup announced the model while a machine reader was parsing: %q", stderr.String())
			}
			if announced {
				t.Fatalf("json: setup announced the agent while a machine reader was parsing: %q", stderr.String())
			}
			continue
		}
		if !announced {
			t.Fatalf("human: setup chose an agent without saying which, so the json case above proves nothing: %q", stderr.String())
		}
		if !strings.Contains(stderr.String(), "model opus") {
			t.Fatalf("human: setup named the agent but not the model, which is the half of the report still unanswered: %q", stderr.String())
		}
	}
}

// TestAnnounceResolvedAgentNamesTheModel answers the report's SECOND sentence,
// "idk what model". The fix is visibility, not a default: setup.go's
// setupBackfillDefaultEffort block already decided not to hardcode a model id
// ("model ids age badly"), and pinning Sonnet or Opus here would be the
// codex-first mistake pointing the other way. So an unpinned model is STATED,

// TestSetupDefaultIsTheShortForm pins the default. The phase view reports what
// the machine did and is still available behind --verbose; what a person gets
// by default is the four-line answer.
func TestSetupDefaultIsTheShortForm(t *testing.T) {
	f := newSetupTestFixture(t)
	rec := &recordedSetup{}
	opts := defaultSetupOptions()
	opts.noDaemon = true
	opts.noBackfill = true

	out := runSetupTerseForTest(t, f, opts, rec)

	if !strings.Contains(out, "Brain turns this repo's history") {
		t.Fatalf("the short form opens by saying what Brain is for:\n%s", out)
	}
	if !strings.Contains(out, "Ready. Try:") {
		t.Fatalf("the short form ends with what to type:\n%s", out)
	}
	// The phase view's vocabulary must be absent, or this is not the short form.
	for _, leaked := range []string{"Detect", "instant core", "FAILED", "Workspace"} {
		if strings.Contains(out, leaked) {
			t.Errorf("phase-view text %q leaked into the default output:\n%s", leaked, out)
		}
	}
	if n := len(strings.Split(strings.TrimSpace(out), "\n")); n > 10 {
		t.Errorf("default output is %d lines; the point is that it is short:\n%s", n, out)
	}
}

